styles:
.demo { display: flex; flex-direction: column; gap: 0.65rem; }
    .demo-row { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem; }
    .demo-bar { display: flex; flex-wrap: wrap; gap: 0.5rem; align-items: center; }
    .demo-bar is-select { min-width: 12rem; }
    .pill {
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      padding: 0.25rem 0.65rem;
      border-radius: 999px;
      background: color-mix(in srgb, var(--is-accent) 14%, transparent);
      border: 1px solid color-mix(in srgb, var(--is-accent) 30%, transparent);
      color: var(--is-accent);
      font-size: 0.72rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }
